                i += 1;
                // Skip since parameter for now
            }
            "-U" | "--until" => {
                i += 1;
                // Skip until parameter for now
            }
            arg if arg.starts_with('-') => {
                eprintln!("  error: invalid command-line arguments");
                eprintln!(" reason: The following argument was not expected: {}", arg);
                std::process::exit(109);
            }
            _ => files.push(args[i].clone()),
        }
        i += 1;
    }

    // Handle special flags first
    if help {
        print_help(program_name);
        return;
    }

    if version {
        print_version();
        return;
    }

    if check_config {
        // Just exit successfully for now
        return;
    }

    if warnings {
        eprintln!("  error: unable to display interactive text UI");
        eprintln!(" reason: stdout is not a TTY");
        eprintln!(" = help: pass the -n option to run lnav in headless mode or don't redirect stdout");
        std::process::exit(1);
    }

    if _update_formats {
        return;
    }

    if _install_formats {
        return;
    }

    if _management_mode {
        return;
    }

    // Handle command validation
    if let Some(ref cmd) = command {
        if !cmd.starts_with(':') && !cmd.starts_with(';') && !cmd.starts_with('|') {
            eprintln!("  error: invalid value for \"-c\" option");
            eprintln!(" --> command-line argument");
            eprintln!(" |  -c {}                                ", cmd);
            eprintln!(" |     ^ command type prefix is missing    ");
            eprintln!(" = help: command arguments must start with one of the following symbols to denote the type of command:");
            eprintln!("            : - an lnav command   (e.g. :goto 42)");
            eprintln!("            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)");
            eprintln!("            | - an lnav script    (e.g. |rename-stdin foo)");
            std::process::exit(105);
        }
    }

    // Handle shell command execution
    if let Some(shell_cmd) = shell_command {
        let output = Command::new("sh")
            .arg("-c")
            .arg(&shell_cmd)
            .output();

        match output {
            Ok(output) => {
                if !output.stdout.is_empty() {
                    print!("{}", String::from_utf8_lossy(&output.stdout));
                }
            }
            Err(_) => {
                std::process::exit(1);
            }
        }
        return;
    }

    // Check if stdout is a TTY
    let stdout_is_tty = std::io::stdout().is_terminal();

    // Check if stdin is available
    let stdin_available = !std::io::stdin().is_terminal();

    // If not headless and no files and stdin is available and stdout is not TTY, error
    if !headless && stdin_available && files.is_empty() && !stdout_is_tty {
        eprintln!("  error: unable to display interactive text UI");
        eprintln!(" reason: stdout is not a TTY");
        eprintln!(" = help: pass the -n option to run lnav in headless mode or don't redirect stdout");
        std::process::exit(1);
    }

    // Handle stdin with timestamp prepending
    if stdin_available && files.is_empty() && !timestamp_input && headless {
        // Read from stdin without timestamps
        let stdin = io::stdin();
        for line in stdin.lock().lines() {
            if let Ok(line) = line {
                println!("{}", line);
            }
        }
        return;
    }

    if stdin_available && timestamp_input && files.is_empty() && headless {
        // Read from stdin with timestamps
        let stdin = io::stdin();
        for line in stdin.lock().lines() {
            if let Ok(line) = line {
                let ts = get_current_time();
                println!("{} {}", ts, line);
            }
        }
        return;
    }

    // Check if we need files
    if files.is_empty() {
        if no_default {
            return;
        }
        eprintln!("  error: nothing to do");
        eprintln!(" reason: no files given or default files found");
        eprintln!(" = help: use the \"-N\" option to open lnav without loading any files");
        std::process::exit(1);
    }

    // Collect all files
    match collect_files(&files, recursive) {
        Ok(collected_files) => {
            if collected_files.is_empty() && !no_default {
                if !quiet {
                    eprintln!("  error: no files found");
                }
                std::process::exit(1);
            }

            // Read and display logs
            match read_and_sort_logs(&collected_files) {
                Ok(lines) => {
                    if !quiet {
                        for line in lines {
                            println!("{}", line);
                        }
                    }
                }
                Err(e) => {
                    eprintln!("  error: {}", e);
                    std::process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("  error: {}", e);
            std::process::exit(1);
        }
    }
}
