fn collect_files(paths: &[String], recursive: bool) -> io::Result<Vec<PathBuf>> {
    let mut files = Vec::new();

    for path_str in paths {
        let path = Path::new(path_str);

        if path.is_dir() {
            if recursive {
                collect_files_recursive(&path, &mut files)?;
            } else {
                for entry in fs::read_dir(path)? {
                    let entry = entry?;
                    let path = entry.path();
                    if path.is_file() {
                        files.push(path);
                    }
                }
            }
        } else if path.is_file() {
            files.push(path.to_path_buf());
        } else {
            eprintln!("  error: unable to open file: {}", path_str);
            eprintln!(" reason: No such file or directory");
            std::process::exit(1);
        }
    }

    // Sort files for consistent ordering
    files.sort();
    Ok(files)
}

fn collect_files_recursive(dir: &Path, files: &mut Vec<PathBuf>) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            collect_files_recursive(&path, files)?;
        } else if path.is_file() {
            files.push(path);
        }
    }
    Ok(())
}

fn get_current_time() -> String {
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default();

    let secs = now.as_secs();
    let micros = now.subsec_micros();

    // Basic conversion to ISO 8601-like format
    let days_since_epoch = secs / 86400;
    let year = 1970 + days_since_epoch / 365;
    let day_of_year = days_since_epoch % 365;

    let month = (day_of_year / 30).min(11) + 1;
    let day = (day_of_year % 30) + 1;
    let hour = (secs % 86400) / 3600;
    let minute = (secs % 3600) / 60;
    let second = secs % 60;

    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}+0000", 
        year, month, day, hour, minute, second, micros)
}

fn read_and_sort_logs(files: &[PathBuf]) -> io::Result<Vec<String>> {
    let mut entries: Vec<(String, String)> = Vec::new();

    for file_path in files {
        let file = fs::File::open(file_path)?;
        let reader = BufReader::new(file);

        for line in reader.lines() {
            let line = line?;
            // Extract timestamp if present, otherwise use line itself for sorting
            let sort_key = extract_timestamp(&line).unwrap_or_else(|| line.clone());
            entries.push((sort_key, line));
        }
    }

    // Sort by timestamp key
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    let result = entries.into_iter().map(|(_, line)| line).collect();
    Ok(result)
}

fn extract_timestamp(line: &str) -> Option<String> {
    // Try to find a timestamp at the beginning
    if let Some(end) = line.find(' ') {
        if end > 5 && end < 30 {
            let potential_ts = &line[..end];
            // Check if it looks like a timestamp (contains digits and hyphens/colons)
            if potential_ts.contains('-') && potential_ts.contains(':') {
                return Some(potential_ts.to_string());
            }
        }
    }
    None
}

