}

fn print_version() {
    println!("lnav {}", VERSION);
}

fn collect_files(paths: &[String], recursive: bool) -> io::Result<Vec<PathBuf>> {
    let mut files = Vec::new();

    for path_str in paths {
        let path = Path::new(path_str);

        if path.is_dir() {
            if recursive {
                collect_files_recursive(&path, &mut files)?;
            } else {
                for entry in fs::read_dir(path)? {
                    let entry = entry?;
                    let path = entry.path();
                    if path.is_file() {
                        files.push(path);
                    }
                }
            }
        } else if path.is_file() {
            files.push(path.to_path_buf());
        } else {
            eprintln!("  error: unable to open file: {}", path_str);
            eprintln!(" reason: No such file or directory");
            std::process::exit(1);
        }
    }

    // Sort files for consistent ordering
    files.sort();
    Ok(files)
}

fn collect_files_recursive(dir: &Path, files: &mut Vec<PathBuf>) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            collect_files_recursive(&path, files)?;
        } else if path.is_file() {
            files.push(path);
        }
    }
    Ok(())
}

fn get_current_time() -> String {
    let now = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default();

    let secs = now.as_secs();
    let micros = now.subsec_micros();

    // Basic conversion to ISO 8601-like format
    let days_since_epoch = secs / 86400;
    let year = 1970 + days_since_epoch / 365;
    let day_of_year = days_since_epoch % 365;

    let month = (day_of_year / 30).min(11) + 1;
    let day = (day_of_year % 30) + 1;
    let hour = (secs % 86400) / 3600;
    let minute = (secs % 3600) / 60;
    let second = secs % 60;

    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}+0000", 
        year, month, day, hour, minute, second, micros)
}

fn read_and_sort_logs(files: &[PathBuf]) -> io::Result<Vec<String>> {
    let mut entries: Vec<(String, String)> = Vec::new();

    for file_path in files {
        let file = fs::File::open(file_path)?;
        let reader = BufReader::new(file);

        for line in reader.lines() {
            let line = line?;
            // Extract timestamp if present, otherwise use line itself for sorting
            let sort_key = extract_timestamp(&line).unwrap_or_else(|| line.clone());
            entries.push((sort_key, line));
        }
    }

    // Sort by timestamp key
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    let result = entries.into_iter().map(|(_, line)| line).collect();
    Ok(result)
}

fn extract_timestamp(line: &str) -> Option<String> {
    // Try to find a timestamp at the beginning
    if let Some(end) = line.find(' ') {
        if end > 5 && end < 30 {
            let potential_ts = &line[..end];
            // Check if it looks like a timestamp (contains digits and hyphens/colons)
            if potential_ts.contains('-') && potential_ts.contains(':') {
                return Some(potential_ts.to_string());
            }
        }
    }
    None
}

fn is_dev_null_or_pipe_broken() -> bool {
    // Check where stdin is connected to
    if let Ok(target) = std::fs::read_link("/proc/self/fd/0") {
        let target_str = target.to_string_lossy();
        // If it's /dev/null, return true (should error)
        if target_str.contains("/dev/null") {
            return true;
        }
        // If it's a pipe, return false (has data or will have)
        if target_str.contains("pipe:") {
            return false;
        }
        // If it's a regular file, return false (has content or is empty but still valid)
        if target_str.contains("/") {
            return false;
        }
    }
    false
}

fn process_stdin(timestamp_input: bool, quiet: bool) -> bool {
    // Check if stdin is /dev/null
    if is_dev_null_or_pipe_broken() {
        return false;
    }

    // Try to read lines
    let stdin = io::stdin();
    let reader = BufReader::new(stdin.lock());
    let mut has_lines = false;

    for line in reader.lines() {
        has_lines = true;
        if let Ok(line) = line {
            if !quiet {
                if timestamp_input {
                    let ts = get_current_time();
                    println!("{} {}", ts, line);
                } else {
                    println!("{}", line);
                }
            }
        }
    }

    has_lines
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let program_name = args.get(0).map(|s| s.as_str()).unwrap_or("lnav");

    // Parse arguments manually to handle edge cases
    let mut help = false;
    let mut version = false;
    let mut headless = false;
    let mut no_default = false;
    let mut quiet = false;
    let mut recursive = false;
    let mut _rotated = false;
    let mut timestamp_input = false;
    let mut check_config = false;
    let mut warnings = false;
    let mut _update_formats = false;
    let mut _install_formats = false;
    let mut _management_mode = false;
    let mut _debug_file = None;
    let mut _config_dir = None;
    let mut command = None;
    let mut _command_file = None;
    let mut shell_command = None;
    let mut files = Vec::new();

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" => help = true,
            "-H" => {},
            "-V" => version = true,
            "-n" => headless = true,
            "-N" => no_default = true,
            "-q" => quiet = true,
            "-r" => recursive = true,
            "-R" => _rotated = true,
            "-t" => timestamp_input = true,
            "-C" => check_config = true,
            "-W" => warnings = true,
            "-u" => _update_formats = true,
            "-i" => _install_formats = true,
            "-m" => _management_mode = true,
            "-d" => {
                i += 1;
                if i < args.len() {
                    _debug_file = Some(args[i].clone());
                }
            }
            "-I" => {
                i += 1;
                if i < args.len() {
                    _config_dir = Some(args[i].clone());
                }
            }
            "-c" => {
                i += 1;
                if i < args.len() {
                    command = Some(args[i].clone());
                }
            }
            "-f" => {
                i += 1;
                if i < args.len() {
                    _command_file = Some(args[i].clone());
                }
            }
            "-e" => {
                i += 1;
                if i < args.len() {
                    shell_command = Some(args[i].clone());
                }
            }
            "-S" | "--since" => {
                i += 1;
                // Skip since parameter for now
            }
            "-U" | "--until" => {
                i += 1;
                // Skip until parameter for now
            }
            arg if arg.starts_with('-') => {
                eprintln!("  error: invalid command-line arguments");
                eprintln!(" reason: The following argument was not expected: {}", arg);
                std::process::exit(109);
            }
            _ => files.push(args[i].clone()),
        }
        i += 1;
    }

    // Handle special flags first
    if help {
        print_help(program_name);
        return;
    }

    if version {
        print_version();
        return;
    }

    if check_config {
        // Just exit successfully for now
        return;
    }

    if warnings {
        eprintln!("  error: unable to display interactive text UI");
        eprintln!(" reason: stdout is not a TTY");
        eprintln!(" = help: pass the -n option to run lnav in headless mode or don't redirect stdout");
        std::process::exit(1);
    }

    if _update_formats {
        return;
    }

    if _install_formats {
        return;
    }

    if _management_mode {
        return;
    }

    // Handle command validation
    if let Some(ref cmd) = command {
        if !cmd.starts_with(':') && !cmd.starts_with(';') && !cmd.starts_with('|') {
            eprintln!("  error: invalid value for \"-c\" option");
            eprintln!(" --> command-line argument");
            eprintln!(" |  -c {}                                ", cmd);
            eprintln!(" |     ^ command type prefix is missing    ");
            eprintln!(" = help: command arguments must start with one of the following symbols to denote the type of command:");
            eprintln!("            : - an lnav command   (e.g. :goto 42)");
            eprintln!("            ; - an SQL statement  (e.g. ;SELECT * FROM syslog_log)");
            eprintln!("            | - an lnav script    (e.g. |rename-stdin foo)");
            std::process::exit(105);
        }
    }

    // Handle shell command execution
    if let Some(shell_cmd) = shell_command {
        let output = Command::new("sh")
            .arg("-c")
            .arg(&shell_cmd)
            .output();

        match output {
            Ok(output) => {
                if !output.stdout.is_empty() {
                    print!("{}", String::from_utf8_lossy(&output.stdout));
                }
            }
            Err(_) => {
                std::process::exit(1);
            }
        }
        return;
    }

    // Check if stdout is a TTY
    let stdout_is_tty = std::io::stdout().is_terminal();

    // Check if stdin is a TTY
    let stdin_is_tty = std::io::stdin().is_terminal();

    // If not headless and stdout is not a TTY and no files, error
    if !headless && !stdout_is_tty && files.is_empty() {
        eprintln!("  error: unable to display interactive text UI");
        eprintln!(" reason: stdout is not a TTY");
        eprintln!(" = help: pass the -n option to run lnav in headless mode or don't redirect stdout");
        std::process::exit(1);
    }

    // Handle stdin processing in headless mode with no files
    if headless && files.is_empty() && !stdin_is_tty {
        // Try to process stdin
        if process_stdin(timestamp_input, quiet) {
            return;
        }
        // If process_stdin returned false (no data or dev/null), fall through to error
    }

    // Check if we need files
    if files.is_empty() {
        if no_default {
            return;
        }
        eprintln!("  error: nothing to do");
        eprintln!(" reason: no files given or default files found");
        eprintln!(" = help: use the \"-N\" option to open lnav without loading any files");
        std::process::exit(1);
    }

    // Collect all files
    match collect_files(&files, recursive) {
        Ok(collected_files) => {
            if collected_files.is_empty() && !no_default {
                if !quiet {
                    eprintln!("  error: no files found");
                }
                std::process::exit(1);
            }

            // Read and display logs
            match read_and_sort_logs(&collected_files) {
                Ok(lines) => {
                    if !quiet {
                        for line in lines {
                            println!("{}", line);
                        }
                    }
                }
                Err(e) => {
                    eprintln!("  error: {}", e);
                    std::process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("  error: {}", e);
            std::process::exit(1);
        }
    }
}
