}

fn read_and_sort_logs(files: &[PathBuf]) -> io::Result<Vec<String>> {
    let mut entries: Vec<(String, String)> = Vec::new();

    for file_path in files {
        let file = fs::File::open(file_path)?;
        let reader = BufReader::new(file);

        for line in reader.lines() {
            let line = line?;
            // Extract timestamp if present, otherwise use line itself for sorting
            let sort_key = extract_timestamp(&line).unwrap_or_else(|| line.clone());
            entries.push((sort_key, line));
        }
    }

    // Sort by timestamp key
    entries.sort_by(|a, b| a.0.cmp(&b.0));

    let result = entries.into_iter().map(|(_, line)| line).collect();
    Ok(result)
}

fn extract_timestamp(line: &str) -> Option<String> {
    // Try to find a timestamp at the beginning
    if let Some(end) = line.find(' ') {
        if end > 5 && end < 30 {
            let potential_ts = &line[..end];
            // Check if it looks like a timestamp (contains digits and hyphens/colons)
            if potential_ts.contains('-') && potential_ts.contains(':') {
                return Some(potential_ts.to_string());
            }
        }
    }
    None
}

fn is_dev_null_or_pipe_broken() -> bool {
    // Check where stdin is connected to
