        if target_str.contains("/dev/null") {
            return true;
        }
        // If it's a pipe, return false (has data or will have)
        if target_str.contains("pipe:") {
            return false;
        }
        // If it's a regular file, return false (has content or is empty but still valid)
        if target_str.contains("/") {
            return false;
        }
    }
    false
}

