                        }
                    }
                }
                Err(e) => {
                    eprintln!("  error: {}", e);
                    std::process::exit(1);
                }
            }
        }
        Err(e) => {
            eprintln!("  error: {}", e);
            std::process::exit(1);
        }
    }
}
